const today = new Date();
const weekNumber = Math.floor((today.getDate() - 1) / 7) + 1; // Gets week 1-5 of the month

const schedule = {
  1: 'Franchising',
  2: 'Entrepreneurship',
  3: 'Business Consultancy',
  4: 'Mentorship',
  5: 'Success Stories'
};

const day = today.toLocaleString('en-US', { weekday: 'long' });

// Only post on Wednesday
if (day === 'Thursday') {
  const category = schedule[weekNumber] || schedule[1];
  return [{ json: { category: category.toLowerCase().replace(/\s+/g, '-') } }];
}

