return items.map(inputItem => {

  // Support both RSS and Atom feeds
  const rssItems =
    inputItem.json?.rss?.channel?.item ||
    inputItem.json?.feed?.entry ||
    [];

  const category = inputItem.json?.category || "unknown";
  const item = rssItems[0] || {};

  // --- UNIVERSAL TITLE EXTRACTION ---
  const title =
    (typeof item.title === "string" && item.title) ||
    (item.title?.["_"]) ||                     // Atom style
    (item.title?.["#text"]) ||                 // Alternative Atom parse
    (Array.isArray(item.title) && item.title[0]) ||
    (typeof item.description === "string" && item.description) ||
    (Array.isArray(item.description) && item.description[0]) ||
    "No title";

  // --- UNIVERSAL LINK EXTRACTION ---
  function getLink(it) {
    if (!it) return "";

    // RSS style
    if (typeof it.link === "string") return it.link;
    if (Array.isArray(it.link) && typeof it.link[0] === "string") return it.link[0];

    // Atom <link href="">
    if (typeof it.link === "object" && it.link.href) return it.link.href;

    // Fallback: extract from description
    if (typeof it.description === "string") {
      const match = it.description.match(/href="([^"]+)"/);
      if (match) return match[1];
    }
    if (Array.isArray(it.description) && typeof it.description[0] === "string") {
      const match = it.description[0].match(/href="([^"]+)"/);
      if (match) return match[1];
    }

    return "";
  }

  // --- UNIVERSAL IMAGE EXTRACTION ---
  function getImage(it) {
    if (!it) return null;

    // <media:content>
    const mc = it["media:content"];
    if (Array.isArray(mc) && mc[0]?.$?.url) return mc[0].$.url;
    if (mc?.$?.url) return mc.$.url;

    // <enclosure>
    const enc = it.enclosure;
    if (Array.isArray(enc) && enc[0]?.$?.url) return enc[0].$.url;
    if (enc?.$?.url) return enc.$.url;

    return null;
  }

  return {
    json: {
      title,
      link: getLink(item),
      category,
      imageUrl: getImage(item),
      imageAlt: title
    }
  };
});
